        list.add(new ItemModel("إنّ اتقّاء الله تعالى يكون باتباع ما أمرنا به في القرآن الكريم، وقد ذكر سبحانه وتعالى على لسان الرسول صلى الله عليه وسلم: (قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ) [آل عمران: 31] وهذا يعني أنّه سبحانه جعل اتباع الرسول صلى الله عليه وسلم من محبّة الله تعالى، لذا سنذكر في هذا المقال كيف نتبع سنة الرسول صلى الله عليه وسلم.","اتباع سنة الرسول صلى الله عليه وسلم"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى) [متفق عليه]. فالنية الصادقة لله تعالى هي أساس قبول العمل، فاحرص على أن تكون أعمالك كلها خالصة لوجه الله.","الإخلاص وصدق النية"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم لأبي ذر رضي الله عنه: (اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ) [رواه الترمذي وحسّنه]. وهي وصية جامعة بين حق الله وحق العباد.","تقوى الله وحسن الخلق"));
        list.add(new ItemModel("جاء رجل إلى النبي صلى الله عليه وسلم فقال: أوصني، قال: (لَا تَغْضَبْ)، فردد مراراً، قال: (لَا تَغْضَبْ) [رواه البخاري]. فالغضب مفتاح كل شر، ومن ملك نفسه عند الغضب فقد ملك زمام أمره.","وصية: لا تغضب"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْراً أَوْ لِيَصْمُتْ) [متفق عليه]. فاللسان من أعظم أسباب دخول الجنة أو النار، فاحفظه من الغيبة والنميمة وفضول الكلام.","حفظ اللسان"));
        list.add(new ItemModel("جاء رجل فقال: يا رسول الله، من أحق الناس بحسن صحابتي؟ قال: (أُمُّكَ)، قال: ثم من؟ قال: (أُمُّكَ)، قال: ثم من؟ قال: (أُمُّكَ)، قال: ثم من؟ قال: (ثُمَّ أَبُوكَ) [متفق عليه]. فبر الوالدين من أعظم القربات إلى الله تعالى.","بر الوالدين"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (مَنْ أَحَبَّ أَنْ يُبْسَطَ لَهُ فِي رِزْقِهِ، وَيُنْسَأَ لَهُ فِي أَثَرِهِ، فَلْيَصِلْ رَحِمَهُ) [متفق عليه]. فصلة الرحم سبب لبركة الرزق وطول العمر.","صلة الرحم"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (مَا زَالَ جِبْرِيلُ يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ) [متفق عليه]. فأحسن إلى جارك وكفّ أذاك عنه وتفقد حاله.","الإحسان إلى الجار"));
