        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (عَلَيْكُمْ بِالصِّدْقِ، فَإِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَمَا يَزَالُ الرَّجُلُ يَصْدُقُ وَيَتَحَرَّى الصِّدْقَ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ صِدِّيقاً) [متفق عليه].","الصدق"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (إِنَّ الرِّفْقَ لَا يَكُونُ فِي شَيْءٍ إِلَّا زَانَهُ، وَلَا يُنْزَعُ مِنْ شَيْءٍ إِلَّا شَانَهُ) [رواه مسلم]. فالرفق واللين في التعامل من أخلاق النبوة.","الرفق واللين"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئاً، وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ) [رواه مسلم]. وقال: (تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ) [رواه الترمذي].","المعروف والابتسامة"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (أَفْشُوا السَّلَامَ بَيْنَكُمْ) [رواه مسلم]. وقال: (لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ؟ أَفْشُوا السَّلَامَ بَيْنَكُمْ) [رواه مسلم].","إفشاء السلام"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم لِغُلامٍ: (يَا غُلَامُ، سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ) [متفق عليه]. فمن سنن الطعام التسمية والأكل باليمين والأكل مما يليك.","آداب الطعام"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ) [متفق عليه]. فالسواك سنة مؤكدة، وهو مطهرة للفم مرضاة للرب.","السواك"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (مَنْ صَلَّى اثْنَتَيْ عَشْرَةَ رَكْعَةً فِي يَوْمٍ وَلَيْلَةٍ بُنِيَ لَهُ بِهِنَّ بَيْتٌ فِي الْجَنَّةِ) [رواه مسلم]. وهي السنن الرواتب: ركعتان قبل الفجر، وأربع قبل الظهر وركعتان بعده، وركعتان بعد المغرب، وركعتان بعد العشاء.","السنن الرواتب"));
