        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم لمعاذ رضي الله عنه: (يَا مُعَاذُ، وَاللَّهِ إِنِّي لَأُحِبُّكَ، فَلَا تَدَعْ أَنْ تَقُولَ فِي دُبُرِ كُلِّ صَلَاةٍ: اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ) [رواه أبو داود والنسائي].","وصية النبي لمعاذ بن جبل"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ) [متفق عليه].","الذكر الخفيف الثقيل في الميزان"));
        list.add(new ItemModel("قال رسول الله صلى الله عليه وسلم: (خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ) [رواه البخاري]. فاجعل لك وِرداً يومياً من كتاب الله تلاوةً وتدبراً.","تعلم القرآن وتعليمه"));

